def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"]:
        if marker in blob.lower():
            problems.append(f"  {name}: banned marker '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.182.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.181.0"' not in init:
        sys.exit("ABORT: not at v3.181.0.")
    if "branch_network" not in data:
        sys.exit("ABORT: branch_network module not found in data file.")

    problems = _validate("INV6", LESSONS_I6, QUESTIONS_I6, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_I6))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — INV6 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_I6)
    print(f"INV 6 v3: {len(LESSONS_I6)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_I6):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["branch_network"]["lessons"] = LESSONS_I6
    data["branch_network"]["questions"] = bank
    data["branch_network"]["desc"] = ("The branch network in ZhiftERP: the hub-and-spoke replenishment model and the purchasing boundary; Material Requests with purpose Material Transfer and the item reorder table reasoning on projected quantities; the weekly replenishment run — inputs, the reasoned review pass, the despatch pass through transit, and the closing note; allocation under scarcity by written rule — the essential floor first, pro-rata by sell-through, documented and communicated, with the relief despatch and the pattern check; opening a new branch by transfer with the ninety-day tight cycle and day-sixty reorder levels; laterals, returns, and the exception purchase lane; and the six branch reads on their cadences.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.181.0"', '"3.182.0"'))
    print("  data: INVENTORY 6 lessons + bank REPLACED (style v3, strict manual register)")
    print("wrote __version__ -> 3.182.0")


if __name__ == "__main__":
    main()
